	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		ForecastLine
	 */
		public ForecastLine createForecastLine( CreateForecastLineCommand command ) {

		ForecastLine entity = new ForecastLine();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setForecastLineId( command.getForecastLineId() );
            entity.setPeriod( command.getPeriod() );
            entity.setQuantity( command.getQuantity() );
            entity.setConfidence( command.getConfidence() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of ForecastLine {0} ", entity.toString() );

		return entity;
	}

